macro_rules! implement {
    ($kind:ident, $digits:expr) => {
        impl core::fmt::$kind for Digest {
            fn fmt(&self, formatter: &mut core::fmt::Formatter) -> core::fmt::Result {
                let mut s = [0u8; 32];
                for (i, value) in self.0.iter().enumerate() {
                    s[2 * i] = $digits[(value >> 4) as usize];
                    s[2 * i + 1] = $digits[(value & 15) as usize];
                }
                // ASCII digits only; write_str ignores flags, as the per-byte write! did
                formatter.write_str(core::str::from_utf8(&s).unwrap())
            }
        }
    };
}

